func (r *Registry) getCluster(endpoints []string, credentials ...string) *cluster {
	username, password := "", ""
	if len(credentials) > 0 { username = credentials[0] }
	if len(credentials) > 1 { password = credentials[1] }
	clusterKey := getClusterKey(endpoints) + endpointsSeparator + username + endpointsSeparator + password
	r.lock.Lock()
	defer r.lock.Unlock()
	c, ok := r.clusters[clusterKey]
	if !ok {
		c = newCluster(endpoints)
		c.username = username
		c.password = password
		c.key = clusterKey
		r.clusters[clusterKey] = c
	}
	return c
}

