func (c *cluster) newClient() (EtcdClient, error) {
	var cli EtcdClient
	var err error
	if c.username == "" && c.password == "" {
		cli, err = NewClient(c.endpoints)
	} else {
		cli, err = DialClient(c.endpoints, c.username, c.password)
	}
	if err != nil {
		return nil, err
	}
	go c.watchConnState(cli)
	return cli, nil
}

func NewPublisher(endpoints []string, key, value string, opts ...PublisherOption) *Publisher {
	publisher := &Publisher{
		endpoints: endpoints, key: key, value: value,
		quit: syncx.NewDoneChan(),
		pauseChan: make(chan lang.PlaceholderType),
		resumeChan: make(chan lang.PlaceholderType),
	}
	for _, opt := range opts { opt(publisher) }
	return publisher
}

func WithEtcdAuth(username, password string) PublisherOption {
	return func(p *Publisher) {
		p.username = username
		p.password = password
	}
}

func (p *Publisher) KeepAlive() error {
	cli, err := internal.GetRegistry().GetConn(p.endpoints, p.username, p.password)
	if err != nil { return err }
	p.lease, err = p.register(cli)
	if err != nil { return err }
	proc.AddWrapUpListener(func() { p.Stop() })
	return p.keepAliveAsync(cli)
}

type subOptions struct {
	exclusive bool
	username string
	password string
}

func NewSubscriber(endpoints []string, key string, opts ...SubOption) (*Subscriber, error) {
	var subOpts subOptions
	for _, opt := range opts { opt(&subOpts) }
	sub := &Subscriber{items: newContainer(subOpts.exclusive)}
	if err := internal.GetRegistry().Monitor(endpoints, key, sub.items, subOpts.username, subOpts.password); err != nil {
		return nil, err
	}
	return sub, nil
}

func WithSubscriberEtcdAuth(username, password string) SubOption {
	return func(opts *subOptions) {
		opts.username = username
		opts.password = password
	}
}

func BuildDiscovTarget(endpoints []string, key string, credentials ...string) string {
	authority := strings.Join(endpoints, resolver.EndpointSep)
	if len(credentials) > 0 && credentials[0] != "" {
		authority = url.QueryEscape(credentials[0]) + ":" + url.QueryEscape(credentials[1]) + "@" + authority
	}
	return fmt.Sprintf("%s://%s/%s", resolver.DiscovScheme, authority, key)
}

func NewClient(c RpcClientConf, options ...ClientOption) (Client, error) {
	var opts []ClientOption
	if c.HasCredential() {
		opts = append(opts, WithDialOption(grpc.WithPerRPCCredentials(&auth.Credential{App: c.App, Token: c.Token})))
	}
	if c.Timeout > 0 { opts = append(opts, WithTimeout(time.Duration(c.Timeout)*time.Millisecond)) }
	if c.Retry { opts = append(opts, WithRetry()) }
	opts = append(opts, options...)
	var target string
	var err error
	if len(c.Endpoints) > 0 {
		target = internal.BuildDirectTarget(c.Endpoints)
	} else if len(c.Target) > 0 {
		target = c.Target
	} else {
		if err = c.Etcd.Validate(); err != nil { return nil, err }
		target = internal.BuildDiscovTarget(c.Etcd.Hosts, c.Etcd.Key, c.Etcd.Username, c.Etcd.Password)
	}
	client, err := internal.NewClient(target, opts...)
	if err != nil { return nil, err }
	return &RpcClient{client: client}, nil
}

func (b *discovBuilder) Build(target resolver.Target, cc resolver.ClientConn, opts resolver.BuildOptions) (
	resolver.Resolver, error) {
	authority := target.Authority
	var subOpts []discov.SubOption
	if index := strings.IndexByte(authority, '@'); index >= 0 {
		userInfo := strings.SplitN(authority[:index], ":", 2)
		if len(userInfo) != 2 { return nil, fmt.Errorf("invalid etcd credentials in discovery target") }
		username, err := url.QueryUnescape(userInfo[0])
		if err != nil { return nil, err }
		password, err := url.QueryUnescape(userInfo[1])
		if err != nil { return nil, err }
		subOpts = append(subOpts, discov.WithSubscriberEtcdAuth(username, password))
		authority = authority[index+1:]
	}
	hosts := strings.FieldsFunc(authority, func(r rune) bool { return r == EndpointSepChar })
	sub, err := discov.NewSubscriber(hosts, target.Endpoint, subOpts...)
	if err != nil { return nil, err }
	update := func() {
		var addrs []resolver.Address
		for _, val := range subset(sub.Values(), subsetSize) {
			addrs = append(addrs, resolver.Address{Addr: val})
		}
		if err := cc.UpdateState(resolver.State{Addresses: addrs}); err != nil { logx.Error(err) }
	}
	sub.AddListener(update)
	update()
	return &nopResolver{cc: cc}, nil
}

